function getLabels(m) {
  const { java, source } = this;
  java.toast(m)
  // 获取当前模式的缓存key
  const cacheKey = m == '漫画' ? 'mh_labels' : 'lf_labels';
  const cached = source.get(cacheKey);
  const upTime = source.get('upTime');

  // 有缓存且未过期，直接返回
  if (cached != '' && upTime != '' && upTime > Date.now()) {
    return cached;
  }

  // 请求新数据
  const url = m == '漫画' 
    ? 'https://macapi1.com/ehentai/content-labels'
    : 'https://macapi1.com/anilist/genres';

  if (!url) return null;

  const resp = java.ajax(url);

  // 更新缓存
  if (resp) {
    source.put(cacheKey, resp);
    source.put('upTime', Date.now() + 21600000);
  }

  return resp;
}

